using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Options;
using Microsoft.Extensions.Logging;

namespace AuthLib.OAuth
{
    public class OAuthRedirectOptions
    {
        public List<string> AllowedRedirectDomains { get; set; } = new();
        public string DefaultRedirectUri { get; set; } = "/dashboard";
        public bool EnforceHttps { get; set; } = true;
        public int MaxRedirectLength { get; set; } = 2048;
    }

    public class RedirectUriValidator
    {
        private readonly OAuthRedirectOptions _options;
        private readonly ILogger<RedirectUriValidator> _logger;

        public RedirectUriValidator(IOptions<OAuthRedirectOptions> options, ILogger<RedirectUriValidator> logger)
        {
            _options = options.Value;
            _logger = logger;
        }

        public bool IsValidRedirectUri(string redirectUri, out Uri parsedUri)
        {
            parsedUri = null;

            if (string.IsNullOrWhiteSpace(redirectUri))
                return false;

            if (redirectUri.Length > _options.MaxRedirectLength)
                return false;

            // Reject javascript: and data: schemes
            if (redirectUri.StartsWith("javascript:", StringComparison.OrdinalIgnoreCase) ||
                redirectUri.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
                return false;

            if (!Uri.TryCreate(redirectUri, UriKind.RelativeOrAbsolute, out parsedUri))
                return false;

            if (!parsedUri.IsAbsoluteUri)
                return true; // Relative URIs are safe - same origin

            if (_options.EnforceHttps && parsedUri.Scheme != "https")
                return false;

            return IsDomainAllowed(parsedUri.Host);
        }

        private bool IsDomainAllowed(string host)
        {
            return _options.AllowedRedirectDomains.Any(allowed =>
                host.EndsWith(allowed, StringComparison.OrdinalIgnoreCase));
        }
    }

    public class OAuthCallbackMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly RedirectUriValidator _validator;
        private readonly OAuthRedirectOptions _options;
        private readonly ILogger<OAuthCallbackMiddleware> _logger;

        public OAuthCallbackMiddleware(
            RequestDelegate next,
            RedirectUriValidator validator,
            IOptions<OAuthRedirectOptions> options,
            ILogger<OAuthCallbackMiddleware> logger)
        {
            _next = next;
            _validator = validator;
            _options = options.Value;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (!context.Request.Path.StartsWithSegments("/oauth/callback"))
            {
                await _next(context);
                return;
            }

            var code = context.Request.Query["code"].FirstOrDefault();
            var state = context.Request.Query["state"].FirstOrDefault();
            var redirectUri = context.Request.Query["redirect_uri"].FirstOrDefault();

            if (string.IsNullOrEmpty(code) || string.IsNullOrEmpty(state))
            {
                context.Response.StatusCode = 400;
                return;
            }

            // Validate CSRF state token
            if (!await ValidateStateToken(context, state))
            {
                _logger.LogWarning("Invalid state token from {IP}", context.Connection.RemoteIpAddress);
                context.Response.StatusCode = 403;
                return;
            }

            // Exchange code for token (simplified)
            var token = await ExchangeCodeForToken(code);
            if (token == null)
            {
                context.Response.StatusCode = 401;
                return;
            }

            // Set auth cookie
            context.Response.Cookies.Append("auth_token", token, new CookieOptions
            {
                HttpOnly = true,
                Secure = true,
                SameSite = SameSiteMode.Lax,
                MaxAge = TimeSpan.FromHours(8)
            });

            // Determine redirect target
            var finalRedirect = DetermineRedirectTarget(redirectUri, context);
            context.Response.Redirect(finalRedirect);
        }

        private string DetermineRedirectTarget(string requestedUri, HttpContext context)
        {
            if (string.IsNullOrEmpty(requestedUri))
                return _options.DefaultRedirectUri;

            // Normalize the URI before validation
            var normalized = NormalizeRedirectUri(requestedUri, context);

            if (_validator.IsValidRedirectUri(normalized, out var parsed))
                return normalized;

            _logger.LogWarning("Rejected redirect to {Uri}", requestedUri);
            return _options.DefaultRedirectUri;
        }

        private string NormalizeRedirectUri(string uri, HttpContext context)
        {
            // Handle protocol-relative URLs by prepending scheme
            if (uri.StartsWith("//"))
            {
                var scheme = context.Request.IsHttps ? "https" : "http";
                return scheme + ":" + uri;
            }

            // Decode percent-encoded characters for consistent validation
            var decoded = Uri.UnescapeDataString(uri);

            // Handle backslash normalization (browsers treat \ as /)
            decoded = decoded.Replace('\\', '/');

            return decoded;
        }

        private Task<bool> ValidateStateToken(HttpContext context, string state)
        {
            // In production: validate against distributed cache (Redis)
            // Simplified for demonstration
            var sessionState = context.Request.Cookies["oauth_state"];
            return Task.FromResult(
                !string.IsNullOrEmpty(sessionState) &&
                string.Equals(sessionState, state, StringComparison.Ordinal));
        }

        private Task<string> ExchangeCodeForToken(string code)
        {
            // Simplified - would call token endpoint
            if (!string.IsNullOrEmpty(code) && code.Length > 10)
                return Task.FromResult("valid_token_" + Guid.NewGuid().ToString("N"));
            return Task.FromResult<string>(null);
        }
    }
}
